snippet_css:
:root{
  --bg: #FFFFFF;
  --fg: #141414;
  --muted: #525252;
  --surface: #F2F2F2;
  --border: #141414;
  --accent: #C81E1E;
  --accent-fg: #FFFFFF;
  --radius: 0px;
  --radius-sm: 0px;
  --shadow: none;
  --btn-shadow: none;
  --art-bg: linear-gradient(135deg,#141414 0 38%,#C81E1E 38% 62%,#E5E5E5 62%);
  --media-bg: linear-gradient(180deg,#FFFFFF,#EDEDED);
  --cta-bg: #EDEDED;
  --input-bg: #FFFFFF;
  --ok: #0E6B3C;
  --warn: #B3121B;
  --font-display: Inter,'Noto Sans TC',sans-serif;
  --font-body: Inter,'Noto Sans TC',sans-serif;
  --font-mono: 'Inter',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
